def transform(grid):
    g=[row[:] for row in grid]
    # Fill the interior of the outer rectangular frame with color 2,
    # while drawing a smaller centered rectangular frame in color 5.
    rs=[r for r,row in enumerate(g) if 5 in row]
    cs=[c for c in range(len(g[0])) if any(row[c]==5 for row in g)]
    r0,r1=min(rs),max(rs); c0,c1=min(cs),max(cs)
    h=r1-r0+1; w=c1-c0+1
    inset=max(1,(min(h,w)-1)//4)
    a,b=r0+inset,r1-inset
    x,y=c0+inset,c1-inset
    for r in range(r0+1,r1):
        for c in range(c0+1,c1):
            g[r][c]=2
    for c in range(x,y+1):
        g[a][c]=5; g[b][c]=5
    for r in range(a,b+1):
        g[r][x]=5; g[r][y]=5
    for r in range(a+1,b):
        for c in range(x+1,y):
            g[r][c]=0
    return g

